{
  "rules": [
    {
      "category": "screening_restriction",
      "title": "FEHA source of income definition and protections",
      "requirement": "Landlords cannot discriminate against tenants or applicants based on their source of income, which includes federal, state, or local housing subsidies such as Section 8 housing vouchers and HUD-VASH vouchers.",
      "requirement_es": "Los propietarios no pueden discriminar a inquilinos o solicitantes según su fuente de ingresos, lo que incluye subsidios de vivienda federales, estatales o locales, como los vales de vivienda de la Sección 8 y los vales HUD-VASH.",
      "key_value": null,
      "coverage_conditions": {
        "type": "ALWAYS",
        "clauses": []
      },
      "exemptions": [
        {
          "description": "Refusal to rent or lease a portion of an owner-occupied single-family house to a person as a roomer or boarder living within the household, provided no more than one roomer or boarder is to live within the household, subject to advertising restrictions.",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "property_type",
                "operator": "==",
                "value": "single_family",
                "note": "portion of an owner-occupied single-family house"
              },
              {
                "field": "owner_occupied",
                "operator": "==",
                "value": true,
                "note": "owner-occupied single-family house"
              }
            ]
          }
        }
      ],
      "effective_date": "2020-01-01",
      "superseded_date": null,
      "status": "enacted",
      "precedence": {
        "relationship": "stacks_with",
        "target_scope": "none",
        "source_language": null
      },
      "penalty": null,
      "source_citation": "Cal. Gov. Code § 12927(c), (i)",
      "quote": {
        "chunk": "c6",
        "start_words": "“Source of income” means lawful, verifiable",
        "end_words": "Affairs Supportive Housing voucher."
      },
      "confidence": 0.95
    }
  ]
}
